  ('chemistry-board-dinajpur-2024-mcq-016', 'class9-chemistry-bn-guide', 'satt-chemistry-board.pdf p6', 'N (g) + 3H (g) ⇔ 2N H (g) + 92 kJ বিক্রিয়াটিতে তাপ প্রয়োগ করলে কী হবে? 2 2 3', 'mcq', '{"ক":"উৎপাদ হ্রাস পাবে।","খ":"উৎপাদ বৃদ্ধি পাবে।","গ":"বিক্রিয়াটি সামনের দিকে অগ্রসর হয়","ঘ":"উৎপন্ন তাপের পরিমাণ বৃদ্ধি পাবে।"}'::jsonb, 'ক', 1, false, 'chemistry-board-dinajpur-2024-mcq', false, 'board-mcq', null, null, 'dinajpur', 2024, true),
